items = [x.strip() for x in raw.split(",") if x.strip()]

# Normalization & filtering
filtered = set()
for item in items:
    name = item.strip().lower()
    # Normalize naming differences
    name = name.replace("_", "-")
    if name in ["torch", "torchvision", "torchaudio", "triton"]:
        continue
    if name.startswith("nvidia-") or name.startswith("cuda-"):
        continue
    # Special git-based packages that need git install or standard package name
    if name == "img2texture":
        filtered.add("git+https://github.com/WASasquatch/img2texture.git")
        continue
    if name == "cstr":
        filtered.add("git+https://github.com/WASasquatch/cstr.git")
        continue
    if name == "ffmpy":
        filtered.add("git+https://github.com/WASasquatch/ffmpy.git")
        continue
    if name == "decorator":
        filtered.add("decorator<5.0,>=4.0.2")
        continue
    if name == "opencv-python":
        filtered.add("opencv-python-headless")
        continue
    if name == "dotenv":
        filtered.add("python-dotenv")
        continue
    filtered.add(item.strip())

# Clean sorted list
final_list = sorted(list(filtered), key=lambda s: s.lower())
print(f"Total Unique Packages: {len(final_list)}")
print("[\n" + ",\n".join(f'    "{p}"' for p in final_list) + "\n]")
